
-- Handbook v1.14 remediation: distinct household/study ledger facts replace generic transaction labels.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'translated record' WHEN 1 THEN 'rehabilitationtranslated record' WHEN 2 THEN 'translated recordpurchase' WHEN 3 THEN 'knee bracetranslated record'
      WHEN 4 THEN 'translated record' WHEN 5 THEN 'translated record' WHEN 6 THEN 'translated record' WHEN 7 THEN 'stationerytranslated record'
      WHEN 8 THEN 'hospitaltranslated record' WHEN 9 THEN 'translated record' WHEN 10 THEN 'follow-up appointmenttranslated record' WHEN 11 THEN 'translated record'
      WHEN 12 THEN 'translated record' WHEN 13 THEN 'translated record' WHEN 14 THEN 'translated record' WHEN 15 THEN 'ice packtranslated record'
      ELSE 'translated record' END AS purpose,
    CASE rowid % 19
      WHEN 0 THEN 'translated recordbudget' WHEN 1 THEN 'translated recordbudget' WHEN 2 THEN 'translated record' WHEN 3 THEN 'translated record'
      WHEN 4 THEN 'translated record' WHEN 5 THEN 'translated record' WHEN 6 THEN 'translated record' WHEN 7 THEN 'translated record'
      WHEN 8 THEN 'translated record' WHEN 9 THEN 'translated record' WHEN 10 THEN 'translated record' WHEN 11 THEN 'translated record'
      WHEN 12 THEN 'translated record' WHEN 13 THEN 'translated record' WHEN 14 THEN 'does not affect exam registration' WHEN 15 THEN 'translated record'
      WHEN 16 THEN 'translated record' WHEN 17 THEN 'translated record' ELSE 'translated record' END AS ledger_state
  FROM transactions WHERE tx_id LIKE 'tx_bg_%'
)
UPDATE transactions
SET counterparty = (SELECT purpose FROM facts WHERE facts.rid=transactions.rowid),
    memo = CASE rowid % 5
      WHEN 0 THEN (SELECT purpose || '；' || ledger_state FROM facts WHERE facts.rid=transactions.rowid)
      WHEN 1 THEN (SELECT ledger_state || 'translated record' || purpose FROM facts WHERE facts.rid=transactions.rowid)
      WHEN 2 THEN (SELECT purpose || '（translated record：' || ledger_state || '）' FROM facts WHERE facts.rid=transactions.rowid)
      WHEN 3 THEN (SELECT 'translated record=' || purpose || '；' || ledger_state FROM facts WHERE facts.rid=transactions.rowid)
      ELSE (SELECT purpose || '，translated record' || ledger_state FROM facts WHERE facts.rid=transactions.rowid)
    END,
    tx_id=replace(tx_id,'tx_bg_','tx_household_ledger_')
WHERE tx_id LIKE 'tx_bg_%';
